self.addEventListener("push",i=>{if(!i.data)return;let t={title:"Notification",body:"You have a new message.",icon:"/icon-192x192.png"};try{t=JSON.parse(i.data.text())}catch{}i.waitUntil(self.registration.showNotification(t.title||"Notification",{body:t.body||"",icon:t.icon||"/icon-192x192.png"}))}),self.addEventListener("notificationclick",i=>{i.notification.close(),i.waitUntil(clients.matchAll({type:"window",includeUncontrolled:!0}).then(i=>{for(let t of i)if("focus"in t)return t.focus();if(clients.openWindow)return clients.openWindow("/")}))});